create policy purchases_view on public.purchases for select using (current_user_has_permission('purchases.view') or current_user_is_manager());
create policy purchase_items_view on public.purchase_items for select using (current_user_has_permission('purchases.view') or current_user_is_manager());
create policy raw_materials_view on public.raw_materials for select using (current_user_has_permission('inventory.view') or current_user_has_permission('purchases.view') or current_user_is_manager());
create policy production_orders_view2 on public.production_orders for select using (current_user_has_permission('production.view') or current_user_is_manager());
