create policy counts_view on public.cash_counts for select using (current_user_has_permission('treasury.view') or current_user_is_manager());
create policy customers_view on public.customers for select using (current_user_has_permission('sales.view') or current_user_is_manager());
create policy departments_view on public.departments for select using (current_user_has_permission('employees.view') or current_user_is_manager());
create policy jobs_view on public.job_titles for select using (current_user_has_permission('employees.view') or current_user_is_manager());
create policy shifts_view on public.shifts for select using (current_user_has_permission('employees.view') or current_user_is_manager());
